using System;
using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "StaffCapacitorOmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/StaffCapacitor Omen Data")]
public class StaffCapacitorOmenData : IncreasePurifyReceivedByEnemiesOmenData
{
	[Header("Sentinel Ring")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.StaffCapacitorFeedbackAction = delegate
		{
			if (ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions.Count == 0)
			{
				omenInstance.PlayBlinkingFeedback();
			}
			else
			{
				omenInstance.StopBlinkingFeedback();
			}
		};
		InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.1f, delegate
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.StaffCapacitorFeedbackAction?.Invoke();
		});
		base.Initialize(omenInstance);
	}

	public override Func<int, int> GetPurifyOmenAction(OmenInstance omenInstance)
	{
		return delegate(int purifyAmount)
		{
			if (currentCompanions.ActiveCompanions.Count == 0)
			{
				omenInstance.ActivateOmenFeedback();
				return purifyAmount + additionalPurifyAmount;
			}
			return purifyAmount;
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.StaffCapacitorFeedbackAction = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetOmenRawLocalizedDescription() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + GetIncreasePurifyReceivedByEnemiesLocalizedString(additionalPurifyAmount).LowercaseFirst();
	}
}
